package com.libertasprimordium.skald

import java.io.File
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFalse
import kotlin.test.assertIs
import kotlin.test.assertTrue

class VaultImportConfinementTest {
    @Test
    fun productionImportsAndExternalReferencesStayWithinReviewedInventory() {
        val files = SourceGuardCorpus.productionRuntimeSourceFiles
        val completePaths = productionRoots.flatMap { root ->
            File(SourceGuardCorpus.repositoryRoot, root).walkTopDown()
                .filter { it.isFile && mustInventoryProductionPath(SourceGuardCorpus.relativePath(it)) }
                .map(SourceGuardCorpus::relativePath).toList()
        }.toSet()
        assertEquals(completePaths, files.map(SourceGuardCorpus::relativePath).toSet(), "No production Kotlin path may escape the cached corpus")
        assertEquals(reviewedImports.keys, files.map(SourceGuardCorpus::relativePath).toSet())
        files.forEach { file ->
            val path = SourceGuardCorpus.relativePath(file)
            assertTrue(
                acceptsReviewedProductionSource(path, SourceGuardCorpus.text(file)),
                "Unreviewed security API surface in $path",
            )
        }
    }

    @Test
    fun sourceRootsHaveNoDirectoryNameExceptions() {
        productionRoots.forEach { root ->
            listOf("tmp", "reports", "out", "build").forEach { name ->
                assertTrue(mustInventoryProductionPath("$root/kotlin/$name/Injected.kt"))
                assertTrue(mustInventoryProductionPath("$root/kotlin/$name/Injected.kts"))
            }
        }
        assertFalse(mustInventoryProductionPath("composeApp/build/Generated.kt"))
    }

    private val productionRoots = listOf("composeApp/src/commonMain", "composeApp/src/androidMain", "composeApp/src/desktopMain")

    private fun mustInventoryProductionPath(path: String): Boolean =
        productionRoots.any { path.startsWith("$it/") } && (path.endsWith(".kt") || path.endsWith(".kts"))

    @Test
    fun generalForeignImportsAliasesQualifiedCallsAndRuntimeLoadingFailClosed() {
        val mutations = listOf(
            "import unreviewed.adapter.Client",
            "import unreviewed.adapter.Client as AllowedName",
            "import unreviewed . adapter . Client",
            "import unreviewed/*comment*/.adapter.Client",
            "fun call() = unreviewed.adapter.Client()",
            "fun generatedCall() = unreviewed.adapter.Client()",
            "fun generatedCall() = unreviewed.adapter.execute()",
            "fun generatedCall() = foreign.execute()",
            "val loaded = unreviewed.adapter.client",
            "val loaded = foreign.client",
            "package approved; import unreviewed.adapter.Client",
            "package approved; val loaded = unreviewed.adapter.client",
            "val generatedProperty = \"${'$'}{unreviewed.adapter.client}\"",
            "val generated = unreviewed.adapter::execute",
            "fun generatedCall() = unreviewed/*split*/.adapter.execute()",
            "fun call() = Class.forName(\"unreviewed.adapter.Client\")",
            "fun call() = loader.loadClass(\"unreviewed.adapter.Client\")",
            "fun call() = System.loadLibrary(\"unreviewed\")",
            "fun call() = Runtime.getRuntime().exec(\"unreviewed\")",
            "external fun invokeNative()",
            "println (\"SYNTHETIC_DIAGNOSTIC\")",
            "println/*split*/ (\"SYNTHETIC_DIAGNOSTIC\")",
            "val call = ::println",
            "val generated = \"${'$'}{run { println (\"SYNTHETIC_DIAGNOSTIC\") }}\"",
            "fun call() = value.javaClass",
            "val generated = \"${'$'}{unreviewed.adapter.Client()}\"",
            "val generated = \"${'$'}{unreviewed/*split*/.adapter/*split*/.Client()}\"",
            "val generated = \"${'$'}{java/*split*/.lang/*split*/.Thread()}\"",
        )
        mutations.forEachIndexed { index, mutation ->
            assertFalse(VaultImportConfinement.accepts(mutation, emptySet()), "Mutation $index was admitted")
        }
    }

    @Test
    fun exactReviewedImportWorksButDoesNotAdmitAliasesWildcardsOrOtherSymbols() {
        val allowed = setOf("approved.api.Value")
        assertTrue(VaultImportConfinement.accepts("import approved.api.Value", allowed))
        assertTrue(VaultImportConfinement.accepts("// ignored ordinary comment\nimport approved.api.Value", allowed))
        assertFalse(VaultImportConfinement.accepts("import approved.api.*", allowed))
        assertFalse(VaultImportConfinement.accepts("import approved.api.Value as Alias", allowed))
        assertFalse(VaultImportConfinement.accepts("import approved.api.Other", allowed))
        assertFalse(VaultImportConfinement.accepts("package approved; import approved.api.Value as Alias", allowed))
        assertFalse(VaultImportConfinement.accepts("import approved.api.Value; import approved.api.Value as Alias", allowed))
        assertFalse(VaultImportConfinement.accepts("fun generatedCall() = other.api.Value()", allowed))
    }

    @Test
    fun actualStartupAndVaultFilesRejectAddedUnqualifiedSideEffectsAndReferences() {
        val paths = listOf(
            "composeApp/src/commonMain/kotlin/com/libertasprimordium/skald/App.kt",
            "composeApp/src/commonMain/kotlin/com/libertasprimordium/skald/security/DisabledSecureStorage.kt",
            "composeApp/src/commonMain/kotlin/com/libertasprimordium/skald/security/EncryptedVaultV1CanonicalArchitectureDecision.kt",
        )
        paths.forEach { path ->
            val file = SourceGuardCorpus.productionRuntimeSourceFiles.single { SourceGuardCorpus.relativePath(it) == path }
            val original = SourceGuardCorpus.text(file)
            assertTrue(acceptsReviewedProductionSource(path, original))
            listOf(
                "\nval unexpected = println (\"SYNTHETIC_DIAGNOSTIC\")",
                "\nval unexpected = println/*comment*/ (\"SYNTHETIC_DIAGNOSTIC\")",
                "\nval unexpected = ::println",
                "\nval unexpected = \"${'$'}{java/*split*/.lang/*split*/.Thread()}\"",
            ).forEachIndexed { index, mutation ->
                assertFalse(acceptsReviewedProductionSource(path, original + mutation), "$path mutation $index was admitted")
            }
        }
    }

    internal fun acceptsReviewedProductionSource(path: String, source: String): Boolean =
        VaultImportConfinement.accepts(source, reviewedImports.getValue(path), reviewedClassLiterals[path].orEmpty(), reviewedQualifiedCalls[path].orEmpty(), reviewedQualifiedReferences.getValue(path), reviewedTemplates[path].orEmpty(), reviewedCallables.getValue(path))

    @Test
    fun privateDeclarationGuardIgnoresLiteralProseButRejectsExecutableSyntaxAndTemplates() {
        assertFalse(VaultImportConfinement.containsPrivateCode("val label = \"Monero private key material\""))
        assertTrue(VaultImportConfinement.containsPrivateCode("private val payload = Unit"))
        assertTrue(VaultImportConfinement.containsPrivateCode("private/*comment*/fun operation() = Unit"))
        assertTrue(VaultImportConfinement.containsPrivateCode("val text = \"${'$'}{object { private val payload = Unit }}\""))
    }

    @Test
    fun actualPrerequisiteAuditRejectsCompleteNestedTemplateMutationsStructurally() {
        val path = "composeApp/src/commonMain/kotlin/com/libertasprimordium/skald/security/SkaldVaultV1ProviderExecutableKatPrerequisiteAudit.kt"
        val file = SourceGuardCorpus.productionRuntimeSourceFiles.single { SourceGuardCorpus.relativePath(it) == path }
        val original = SourceGuardCorpus.text(file)
        assertTrue(acceptsReviewedProductionSource(path, original))
        val target = "${'$'}{categoryNames}"
        assertEquals(1, original.split(target).size - 1)
        val attacks = listOf(
            "categories.map { it.name }.also { println (\"SYNTHETIC_DIAGNOSTIC\") }",
            "categoryNames.also { println/*comment*/ (\"SYNTHETIC_DIAGNOSTIC\") }",
            "categoryNames.run { this }",
            "categoryNames.also { ::println }",
            "categoryNames.also { unreviewed.adapter.execute() }",
        )
        attacks.forEachIndexed { index, expression ->
            val mutated = original.replace(target, "${'$'}{$expression}")
            assertFalse(mutated == original, "Mutation $index did not replace its target")
            assertEquals(
                VaultSourceLexicalScan.Failure.NestedExecutableTemplate,
                assertIs<VaultSourceLexicalScan.Rejected>(VaultSourceLexicalScan.scan(mutated)).reason,
                "Nested mutation $index must fail structurally before template inventory checks",
            )
            assertFalse(acceptsReviewedProductionSource(path, mutated), "Nested mutation $index was admitted")
        }
        val rawTarget = "\"categories=$target, \""
        assertEquals(1, original.split(rawTarget).size - 1)
        val rawMutation = original.replace(rawTarget, "\"\"\"categories=${'$'}{${attacks.first()}}, \"\"\"")
        assertFalse(rawMutation == original)
        assertEquals(
            VaultSourceLexicalScan.Failure.NestedExecutableTemplate,
            assertIs<VaultSourceLexicalScan.Rejected>(VaultSourceLexicalScan.scan(rawMutation)).reason,
        )
        assertFalse(acceptsReviewedProductionSource(path, rawMutation))
    }

    @Test
    fun actualPrerequisiteAuditRejectsUnknownCompleteFlatExpressionsAndSideEffects() {
        val path = "composeApp/src/commonMain/kotlin/com/libertasprimordium/skald/security/SkaldVaultV1ProviderExecutableKatPrerequisiteAudit.kt"
        val file = SourceGuardCorpus.productionRuntimeSourceFiles.single { SourceGuardCorpus.relativePath(it) == path }
        val original = SourceGuardCorpus.text(file)
        val target = "${'$'}{categoryNames}"
        assertEquals(1, original.split(target).size - 1)
        listOf(
            "categoryNames.size",
            "println (\"SYNTHETIC_DIAGNOSTIC\")",
            "println/*comment*/ (\"SYNTHETIC_DIAGNOSTIC\")",
            "::println",
            "unreviewed.adapter.execute()",
        ).forEachIndexed { index, expression ->
            val mutated = original.replace(target, "${'$'}{$expression}")
            assertFalse(mutated == original)
            val scanned = assertIs<VaultSourceLexicalScan.Accepted>(VaultSourceLexicalScan.scan(mutated))
            assertTrue(expression in scanned.templates, "Flat mutation $index was not captured completely")
            assertFalse(acceptsReviewedProductionSource(path, mutated), "Flat mutation $index was admitted")
        }
    }

    @Test
    fun completeTemplateApprovalDoesNotGrantCallableOrReferencePermission() {
        listOf(
            "println (\"SYNTHETIC_DIAGNOSTIC\")",
            "println/*comment*/ (\"SYNTHETIC_DIAGNOSTIC\")",
            "::println",
            "unreviewed.adapter.execute()",
        ).forEach { expression ->
            val source = "val value = \"${'$'}{$expression}\""
            val scanned = assertIs<VaultSourceLexicalScan.Accepted>(VaultSourceLexicalScan.scan(source))
            assertEquals(listOf(expression), scanned.templates)
            assertFalse(VaultImportConfinement.accepts(source, emptySet(), allowedTemplates = setOf(expression)))
        }
    }

    @Test
    fun actualPrerequisiteSourceRejectsSideEffectsAfterEveryLineCommentTerminator() {
        val path = "composeApp/src/commonMain/kotlin/com/libertasprimordium/skald/security/SkaldVaultV1ProviderExecutableKatPrerequisiteAudit.kt"
        val file = SourceGuardCorpus.productionRuntimeSourceFiles.single { SourceGuardCorpus.relativePath(it) == path }
        val original = SourceGuardCorpus.text(file)
        assertTrue(acceptsReviewedProductionSource(path, original))
        listOf("\n", "\r\n", "\r").forEachIndexed { index, newline ->
            val mutated = original + "\n// synthetic comment$newline" +
                "val unexpected = println (\"SYNTHETIC_DIAGNOSTIC\")"
            val scanned = assertIs<VaultSourceLexicalScan.Accepted>(VaultSourceLexicalScan.scan(mutated))
            assertTrue(scanned.code.contains("println ("), "Comment terminator $index hid executable code")
            assertFalse(acceptsReviewedProductionSource(path, mutated), "Comment terminator $index bypassed confinement")
        }
    }

