internal object VaultImportConfinement {
    private val importDeclaration = Regex("""(?m)^\s*import\s+([A-Za-z_][A-Za-z0-9_]*(?:\s*\.\s*[A-Za-z_*][A-Za-z0-9_]*)*)(?:\s+as\s+([A-Za-z_][A-Za-z0-9_]*))?""")
    private val qualifiedType = Regex("""\b(?:[a-z_][A-Za-z0-9_]*\s*\.\s*){2,}[A-Z][A-Za-z0-9_]*""")
    private val qualifiedReference = Regex("""\b[A-Za-z_][A-Za-z0-9_]*(?:\s*\.\s*[A-Za-z_][A-Za-z0-9_]*)+""")
    private val qualifiedCall = Regex("""\b(?:[a-z_][A-Za-z0-9_]*\s*\.\s*){2,}[a-z_][A-Za-z0-9_]*\s*\(""")
    private val qualifiedCallableReference = Regex("""\b(?:[a-z_][A-Za-z0-9_]*\s*\.\s*)+[a-z_][A-Za-z0-9_]*\s*::""")
    private val runtimeEscape = Regex("""\b(?:Class|KClass|ClassLoader|forName|loadClass|loadLibrary|javaClass|classLoader|getDeclaredMethod|getDeclaredMethods|getDeclaredConstructor|getDeclaredConstructors|getDeclaredField|getDeclaredFields|getMethod|getMethods|getConstructor|getConstructors|invokeNative|ProcessBuilder)\b|\bRuntime\s*\.|\bSystem\s*\.\s*load\s*\(|::\s*class\b|\bexternal\s+fun\b""")

    fun accepts(source: String, allowedImports: Set<String>, allowedClassLiterals: Set<String> = emptySet(), allowedQualifiedCalls: Set<String> = emptySet(), allowedQualifiedReferences: Set<String> = allowedImports, allowedTemplates: Set<String> = emptySet(), allowedCallables: Set<String> = emptySet()): Boolean {
        val scanned = VaultSourceLexicalScan.scan(source)
        if (scanned !is VaultSourceLexicalScan.Accepted) return false
        if (scanned.templates.any { it !in allowedTemplates }) return false
        val code = scanned.code
        if (code.any { it.code > 127 || it == '`' }) return false
        val calls = Regex("""\b([A-Za-z_][A-Za-z0-9_]*)\s*(?:\(|\{)""").findAll(code).map { it.groupValues[1] }
        val references = Regex("""::\s*([A-Za-z_][A-Za-z0-9_]*)""").findAll(code).map { it.groupValues[1] }
        if ((calls + references).any { it !in allowedCallables }) return false
        val rawWithoutApprovedLiterals = allowedClassLiterals.fold(code) { text, literal -> text.replace(literal, "") }
        if (runtimeEscape.containsMatchIn(rawWithoutApprovedLiterals)) return false
        if (qualifiedType.findAll(code).any { match ->
                val symbol = match.value.replace(Regex("\\s+"), "")
                symbol !in allowedImports && allowedQualifiedReferences.none { it == symbol || it.startsWith("$symbol.") }
            }) return false
        if (qualifiedCallableReference.containsMatchIn(code)) return false
        if (qualifiedCall.findAll(code).any { match ->
                match.value.removeSuffix("(").replace(Regex("\\s+"), "") !in allowedQualifiedCalls
            }) return false
        if (qualifiedReference.findAll(code).any { match ->
                match.value.replace(Regex("\\s+"), "") !in allowedQualifiedReferences
            }) return false
        val declarations = importDeclaration.findAll(code).toList()
        if (Regex("""\bimport\b""").findAll(code).count() != declarations.size) return false
        if (declarations.any { match ->
                match.groupValues[2].isNotEmpty() ||
                    match.groupValues[1].replace(Regex("\\s+"), "") !in allowedImports
            }) return false
        val withoutImports = importDeclaration.replace(code, "")
        return qualifiedType.findAll(withoutImports).all { match ->
            val symbol = match.value.replace(Regex("\\s+"), "")
            symbol in allowedImports || allowedQualifiedReferences.any { it == symbol || it.startsWith("$symbol.") }
        }
    }

    fun containsPrivateCode(source: String): Boolean = when (val scanned = VaultSourceLexicalScan.scan(source)) {
        is VaultSourceLexicalScan.Accepted -> Regex("""\bprivate\b""").containsMatchIn(scanned.code)
        is VaultSourceLexicalScan.Rejected -> true
    }
}
